const countries = Object.keys(items[0].json);
const output = [];

items.forEach(row => {
  countries.forEach(country => {
    const email = row.json[country];
    if (email && email.includes('@')) {
      output.push({
        json: {
          Email: email,
          Country: country,
          Status: '',
          Sent_At: ''
        }
      });
    }
  });
});
return output;
